<?php
/**
 * Template: Individual Purchase Page
 *
 * This template controls the output for the Vertification email
 * created by the YTISM plugin.
 *
 * How to Override:
 * Copy this file to your theme or child theme in:
 *   yourtheme/ytism/templates/verification-email.php
 *
 * The plugin will automatically load the overridden file instead of this one.
 * (Child theme overrides have priority over parent theme.)
 *
 * Available Variables:
 * - $email    (array) email data
 *
 * Note: Do not edit this file inside the plugin directly,
 *       as your changes will be lost on plugin updates.
 *
 * @package YTISM
 * @subpackage Views
 * @since 1.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

$subject     = $email['subject'] ?? __( 'Your Account Verification', 'ytism' );
$username    = $email['username'] ?? __( 'User', 'ytism' );
$verify_link = $email['verify_link'] ?? home_url();
$is_otp      = $email['is_otp'] ?? false;
$otp         = $email['otp'] ?? '';
$is_forget   = $email['is_forget'] ?? false;

$heading_text = $is_forget ? __( 'Password Recover', 'ytism' ) : __( 'Email Verification', 'ytism' );

$main_message = sprintf(
	/* translators: 1: opening link tag, 2: closing link tag */
	esc_html__(
		'Please %1$sclick here%2$s to verify your email address.%3$sFor your security, the link will expire in 15 minutes.',
		'ytism'
	),
	'<a href="' . esc_url( $verify_link ) . '" style="color:#4B3B77;text-decoration:underline;font-weight:700;font-size:13px;">',
	'</a>',
	'<br />'
);

if ( $is_forget ) {
	// FORGOT PASSWORD CASE.
	if ( $is_otp && ! empty( $otp ) ) {
		// Forgot password with OTP.
		$main_message = sprintf(
			/* translators: 1: OTP code, 2: opening link tag, 3: closing link tag */
			esc_html__(
				'Your password reset code is %1$s. You can use this code to reset your password.%2$sFor your security, the OTP will expire in 15 minutes.',
				'ytism'
			),
			'<span style="color:#4B3B77;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:15px;">' . esc_html( $otp ) . '</span>',
			'<br />'
		);

	} else {
		// Forgot password without OTP.
		$main_message = sprintf(
			/* translators: 1: opening link tag, 2: closing link tag */
			esc_html__(
				'Click %1$shere%2$s to reset your password.%3$sFor your security, the link will expire in 15 minutes.',
				'ytism'
			),
			'<a href="' . esc_url( $verify_link ) . '" style="color:#4B3B77;text-decoration:underline;font-weight:700;font-size:13px;">',
			'</a>',
			'<br />'
		);
	}
} elseif ( $is_otp && ! empty( $otp ) ) {
	// Verification with OTP.
	$main_message = sprintf(
		/* translators: 1: OTP code, 2: opening link tag, 3: closing link tag */
		esc_html__(
			'Your verification code is %1$s. Please use this code to verify your email address.%2$sFor your security, the OTP will expire in 15 minutes.',
			'ytism'
		),
		'<span style="color:#4B3B77;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:15px;">' . esc_html( $otp ) . '</span>',
		'<br />'
	);
} else {
	// Verification without OTP.
	$main_message = sprintf(
		/* translators: 1: opening link tag, 2: closing link tag */
		esc_html__(
			'Please %1$sclick here%2$s to verify your email address.%3$sFor your security, the link will expire in 15 minutes.',
			'ytism'
		),
		'<a href="' . esc_url( $verify_link ) . '" style="color:#4B3B77;text-decoration:underline;font-weight:700;font-size:13px;">',
		'</a>',
		'<br />'
	);
}

$galaxy_bg     = 'https://youtunein-opendata.s3.us-east-1.amazonaws.com/images/email/galaxy.png';
$footer_galaxy = 'https://youtunein-opendata.s3.us-east-1.amazonaws.com/images/email/galaxyFooter.png';
